/* @lc app=leetcode id=3695 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun maxAlternatingSum(nums: IntArray, swaps: Array<IntArray>): Long = IntArray(nums.size) { it }.let { p -> swaps.forEach { (a, b) -> p[find(p, a)] = find(p, b) }.let { nums.indices.groupBy { find(p, it) }.values.sumOf { g -> g.count { it % 2 == 0 }.let { e -> g.map { nums[it].toLong() }.sortedDescending().let { v -> v.take(e).sum() - v.drop(e).sum() } } } } } }